import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Anti-XSS filter - strips script tags and event handlers
    private String sanitizeOutput(String input) {
        if (input == null) return null;
        input = input.replaceAll("(?i)<script[^>]*>.*?</script>", "");
        input = input.replaceAll("(?i)on\\w+\\s*=", "");
        return input;
    }

    // Basic input length check
    private boolean validateInput(String param) {
        return param != null && param.length() <= 200;
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        String reportType = request.getParameter("type");
        String dateFrom = request.getParameter("from");
        String dateTo = request.getParameter("to");
        String department = request.getParameter("dept");
        String sortCol = request.getParameter("sort");
        String sortDir = request.getParameter("dir");

        if (!validateInput(reportType) || !validateInput(dateFrom) || 
            !validateInput(dateTo) || !validateInput(department)) {
            response.sendError(400, "Invalid parameters");
            return;
        }

        // Whitelist report types
        if (!reportType.matches("^(sales|inventory|payroll|expenses)$")) {
            response.sendError(400, "Invalid report type");
            return;
        }

        // Validate date format
        if (!dateFrom.matches("^\\d{4}-\\d{2}-\\d{2}$") || 
            !dateTo.matches("^\\d{4}-\\d{2}-\\d{2}$")) {
            response.sendError(400, "Invalid date format");
            return;
        }

        // Build query - department is parameterized, sort is validated below
        String baseQuery = "SELECT id, description, amount, created_at, department " +
                          "FROM " + reportType + "_reports " +
                          "WHERE created_at BETWEEN ? AND ? ";

        if (department != null && !department.isEmpty()) {
            baseQuery += "AND department = ? ";
        }

        // Sort column validation against allowed set
        String[] allowedSorts = {"id", "description", "amount", "created_at", "department"};
        boolean validSort = false;
        if (sortCol != null) {
            for (String allowed : allowedSorts) {
                if (allowed.equals(sortCol)) {
                    validSort = true;
                    break;
                }
            }
        }

        if (validSort) {
            // Sort direction - developer assumes only ASC/DESC but doesn't strictly validate
            if (sortDir == null) sortDir = "ASC";
            baseQuery += "ORDER BY " + sortCol + " " + sortDir;
        }

        response.setContentType("application/json");
        PrintWriter out = response.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(baseQuery)) {

            stmt.setString(1, dateFrom);
            stmt.setString(2, dateTo);
            if (department != null && !department.isEmpty()) {
                stmt.setString(3, department);
            }

            ResultSet rs = stmt.executeQuery();
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",\n");
                first = false;
                json.append("  {");
                json.append("\"id\":" + rs.getInt("id") + ",");
                json.append("\"description\":\"" + sanitizeOutput(rs.getString("description")) + "\",");
                json.append("\"amount\":" + rs.getDouble("amount") + ",");
                json.append("\"created_at\":\"" + rs.getString("created_at") + "\",");
                json.append("\"department\":\"" + sanitizeOutput(rs.getString("department")) + "\"");
                json.append("}");
            }

            json.append("\n]");
            out.print(json.toString());

        } catch (SQLException e) {
            response.sendError(500, "Database error");
        }
    }
}
